mapper.select:
select tm.msg_id ,tm.msg_content ,tm.update_time ,tm.state ,tm.group_id ,tu.name as createBy , CASE WHEN tm.msg_type = '0' THEN '点赞' WHEN tm.msg_type = '1' THEN '评论' ELSE '未知' END AS msg_type from t_msg tm inner join t_user tu on tm.create_by = tu.user_id where tm.user_id = #{userId} and tm.group_id in #{id}
and tm.msg_content like concat('%', #{kw, jdbcType=VARCHAR}, '%')
order by update_time desc

select msg ,answer ,date_format(create_time,'%Y-%m-%d %H:%i:%s') timestp
from user_chat where user_id =#{param2}
and create_time < #{param1}
order by create_time desc
limit 1
